function button(text,action,cls='secondary'){const b=E('button',text,cls);b.type='button';b.onclick=()=>run(action);return b}
function box(parent,id,cls=''){const b=E('div',undefined,cls);b.id=id;parent.append(b);return b}
function details(parent,title){const d=E('details');d.append(E('summary',title));parent.append(d);return d}
function form(parent,id,fields,submit,handler){const f=E('form');f.id=id;for(const def of fields){const [name,label,type='text',options={}]=def;const l=E('label',label);l.htmlFor=id+'-'+name;let input;if(type==='select'){input=E('select');for(const option of options.options||[])input.add(new Option(typeof option==='string'?option:option[1],typeof option==='string'?option:option[0]));}else input=E(type==='textarea'?'textarea':'input');input.id=id+'-'+name;input.name=name;if(type!=='textarea'&&type!=='select')input.type=type;input.required=!!options.required;if(type==='checkbox')l.className='inline-check';if(options.max)input.maxLength=options.max;if(options.min)input.minLength=options.min;if(options.placeholder)input.placeholder=options.placeholder;if(options.multiple)input.multiple=true;if(options.accept)input.accept=options.accept;if(type==='password')input.autocomplete='off';if(type==='checkbox')l.prepend(input);else l.append(input);if(options.help)l.append(E('small',options.help));f.append(l)}const b=E('button',submit);b.type='submit';f.append(b);f.onsubmit=e=>{e.preventDefault();run(async()=>{const data=Object.fromEntries(new FormData(f));await handler(data,f,e.submitter);});};parent.append(f);return f}
