function choices(parent,id,label){const l=E('label',label),b=E('div',undefined,'choices');b.id=id;const submit=parent.tagName==='FORM'?parent.querySelector('button[type=submit]'):null;if(submit){parent.insertBefore(l,submit);parent.insertBefore(b,submit)}else parent.append(l,b);return b}
function fillChoices(id,items,label,checked=false){const out=$(id);if(!out)return;const old=new Set([...out.querySelectorAll('input:checked')].map(x=>x.value)),had=out.dataset.filled;out.replaceChildren();out.dataset.filled='1';for(const item of items){const l=E('label'),input=E('input');input.type='checkbox';input.value=item.id;input.checked=old.has(item.id)||(!had&&checked);l.append(input,E('span',label(item)));out.append(l)}if(!items.length)out.append(E('p','No items available.','meta'))}
const checked=id=>[...$(id).querySelectorAll('input:checked')].map(x=>x.value);
function fillSelect(id,items,label,placeholder='Choose an item'){const s=$(id);if(!s)return;const old=s.value;s.replaceChildren(new Option(placeholder,''));for(const item of items)s.add(new Option(label(item),item.id));s.value=items.some(x=>x.id===old)?old:''}
function download(data,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([data],{type}));const a=E('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function run(fn){try{await fn()}catch(e){status(e.message,true)}}
function db(action,value){return new Promise((resolve,reject)=>{const r=indexedDB.open('claritypath-private-v3',1);r.onupgradeneeded=()=>r.result.createObjectStore('vault');r.onerror=()=>reject(r.error);r.onsuccess=()=>{const d=r.result,t=d.transaction('vault',action==='get'?'readonly':'readwrite'),s=t.objectStore('vault');const req=action==='get'?s.get('workspace'):s.put(value,'workspace');let result;req.onsuccess=()=>{result=req.result};t.oncomplete=()=>{d.close();resolve(result)};t.onerror=()=>{d.close();reject(t.error)}}})}
async function persistLocal(){if(localKey){const payload={header:localHeader,payload:await V.encrypt(localKey,state,'device-workspace')};await db('put',payload);storedLocal=payload;}}
async function mutate(fn,message){if(remote.saving)throw Error('Wait for the private save to finish before changing records');if(busy)throw Error('Another change is in progress');busy=true;try{await fn();dirty=true;try{await persistLocal()}catch(e){status('Changed in memory; encrypted device save failed. Download a backup. '+e.message,true)}render();if(message)status(message)}finally{busy=false}}
async function add(type,data,message){await mutate(()=>C.append(state,type,selectedCase,data),message)}
function switchPage(name){page=name;document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==name);document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===name?'page':'false'));render();$('page-'+name).querySelector('h1').focus({preventScroll:true});}
